input.command:
# Count packages (directories) outside store/ that reference each key entity type
# Primary entity types: Memo, User, Attachment, Inbox, Reaction, MemoRelation, MemoShare, 
# IdentityProvider, InstanceSetting, UserSetting, UserIdentity, AuthenticationConfigState

for entity in "store\.Memo[^A-Za-z]" "store\.User[^A-Za-z]" "store\.Attachment[^A-Za-z]" "store\.Inbox[^A-Za-z]" "store\.Reaction[^A-Za-z]" "store\.MemoRelation[^A-Za-z]" "store\.MemoShare[^A-Za-z]" "store\.IdentityProvider[^A-Za-z]" "store\.InstanceSetting[^A-Za-z]" "store\.UserSetting[^A-Za-z]" "store\.UserIdentity[^A-Za-z]"; do
  name=$(echo "$entity" | sed 's/store\\.//;s/\[.*//');
  count=$(grep -rn "$entity" /bench/repo --include='*.go' | grep -v '/store/' | sed 's|/bench/repo/||;s|/[^/]*$||' | sort -u | wc -l);
  echo "$name: $count packages";
done

# Let me also check the broader store.* usage including FindUser, UpdateUser, etc.
# to get a full picture of all store types consumed outside
for entity in "store\.User" "store\.Memo" "store\.Attachment" "store\.Inbox" "store\.Reaction" "store\.MemoRelation" "store\.MemoShare" "store\.IdentityProvider" "store\.InstanceSetting" "store\.UserSetting" "store\.UserIdentity" "store\.FindUser" "store\.FindMemo" "store\.UpdateUser" "store\.UpdateMemo" "store\.DeleteUser" "store\.DeleteMemo" "store\.FindAttachment" "store\.UpdateAttachment" "store\.DeleteAttachment" "store\.FindInbox" "store\.UpdateInbox" "store\.DeleteInbox" "store\.FindReaction" "store\.DeleteReaction" "store\.FindMemoRelation" "store\.DeleteMemoRelation" "store\.FindMemoShare" "store\.DeleteMemoShare" "store\.AuthenticationConfig"; do
  name=$(echo "$entity" | sed 's/store\.//');
  pkgs=$(grep -rn "$entity" /bench/repo --include='*.go' | grep -v '/store/' | sed 's|/bench/repo/||;s|/[^/]*$||' | sort -u);
  count=$(echo "$pkgs" | grep -c . 2>/dev/null || echo 0);
  if [ "$count" -gt 0 ]; then
    echo "$name: $count packages";
  fi
done
